#include <stdio.h>
int main(void)
{
    int a[3][3]={{-1,4,2},{4,-1,1},{2,1,-1}},d[3]={0,999,999};
    int used[3]={0},p[3]={-1,-1,-1};
    for(int step=0;step<3;step++) {
        int u=-1;
        for(int v=0;v<3;v++) { if(!used[v] && (u==-1 || d[v]<d[u])) { u=v; } }
        used[u]=1;
        for(int v=0;v<3;v++) {
            if(a[u][v]>=0 && d[u]+a[u][v]<d[v]) { d[v]=d[u]+a[u][v];p[v]=u; }
        }
    }
    (void)p;
    printf("%d\n",d[1]);
    return 0;
}

